package com.cpf.batch.agent; import org.springframework.boot.*; import org.springframework.core.env.Environment; import java.util.Arrays;
public final class AgentProductionSafetyValidator implements ApplicationRunner { private final Environment env;private final AgentProperties p;public AgentProductionSafetyValidator(Environment e,AgentProperties p){env=e;this.p=p;} public void run(ApplicationArguments a){boolean prod=Arrays.stream(env.getActiveProfiles()).anyMatch("prod"::equalsIgnoreCase);if(!prod)return;if(!env.getProperty("server.ssl.enabled",Boolean.class,false))throw new IllegalStateException("Host Agent prod requires TLS");if(!"need".equalsIgnoreCase(env.getProperty("server.ssl.client-auth","")))throw new IllegalStateException("Host Agent prod requires mTLS");if(!p.isRequireSignature())throw new IllegalStateException("signature required");if(p.getArtifactRepositoryBaseUrl()==null||!p.getArtifactRepositoryBaseUrl().startsWith("https://"))throw new IllegalStateException("HTTPS artifact repository required");} }
